import {PEOPLE} from './engine.mjs';
import {SpriteLibrary,Animator,ACTOR_IDS,DIRECTIONS} from './sprites.mjs?v=light-3';
import {Effects} from './effects.mjs';
let state='walk',direction='down',soft=false,last=0,clock=0;const library=new SpriteLibrary(),cards=[];
for(const id of ACTOR_IDS){const card=document.createElement('article');card.className='actor-card';const name=id==='player'?'Votre personnage':PEOPLE[id].name;card.innerHTML=`<header><b>${name}</b><small>20 IMAGES · 1 PERSONNAGE</small></header><canvas width="400" height="190" aria-label="${name}, animations directionnelles"></canvas><div class="labels"><span>UN SEUL SPRITE ANIMÉ</span><span>IMAGES SÉPARÉES</span><span></span><span></span></div>`;document.querySelector('#grid').append(card);cards.push({id,ctx:card.querySelector('canvas').getContext('2d'),animators:DIRECTIONS.map((_,i)=>new Animator(i*.25)),fx:new Effects()});}
library.ready.then(()=>{document.querySelector('#status').textContent=`${library.sheets.size} / 9 personnages prêts · ${library.sheets.size*20} images individuelles chargées`;document.querySelector('#status').dataset.loaded=String(library.sheets.size);});
document.querySelector('#direction').onchange=e=>{direction=e.target.value;};
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{state=b.dataset.state;document.querySelectorAll('[data-state]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));});
document.querySelectorAll('[data-fx]').forEach(b=>b.onclick=()=>cards.forEach(card=>{card.fx.emit(b.dataset.fx,200,144,{count:20});card.fx.label({success:'RÉUSSITE',trust:'CONFIANCE +4',knowledge:'INDICE DÉCOUVERT',train:'SANG-FROID +4'}[b.dataset.fx],200,144,b.dataset.fx);card.animators.forEach(a=>a.trigger('success'));}));
document.querySelector('#soft').onclick=e=>{soft=!soft;e.target.setAttribute('aria-pressed',String(soft));cards.forEach(card=>{card.fx.reduced=soft;card.fx.clear();});};
function frame(t){const dt=Math.min((t-last)/1000||0,.05);last=t;clock+=dt;for(const card of cards){const c=card.ctx;c.fillStyle='#213842';c.fillRect(0,0,400,190);c.strokeStyle='#adbb9d13';c.lineWidth=1;for(let x=0;x<400;x+=20){c.beginPath();c.moveTo(x,0);c.lineTo(x,190);c.stroke();}for(let y=0;y<190;y+=20){c.beginPath();c.moveTo(0,y);c.lineTo(400,y);c.stroke();}card.fx.update(dt);card.fx.drawGround(c);for(let i=0;i<1;i++){const a=card.animators[0];a.update(dt,{distance:['walk','run'].includes(state)?(state==='run'?212:145)*dt:0,direction,running:state==='run',talking:state==='talk',reduced:soft});c.save();c.translate(200,163);c.scale(2.6,2.6);library.draw(c,card.id,0,0,a.pose(),{reduced:soft});c.restore();}card.fx.drawOver(c);}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
